// Build docs/js/community-us-map.js from a Wikimedia Commons blank US map.
//
// Why a script rather than a pasted file
// ──────────────────────────────────────
// Same reason as tools/fetch-bird-photos.js: the licence is fetched from the
// same API call as the artwork, so the credit in the generated file cannot
// drift from the thing it describes. This particular map is CC0, which asks
// for no attribution at all, but the source is recorded anyway — a future
// reader deserves to know where 50 state outlines came from and on what
// terms, and "it was CC0" is not a claim anyone should have to take on trust.
//
// What it produces
// ────────────────
// The source SVG tags each state with class="xx" (its postal code) and a
// <title> holding the full name. Those are pulled out into a plain map of
// code -> path data, so the renderer can draw the states itself and colour
// any subset. Embedding the SVG as an <img> would have been less code and
// would not allow highlighting, which is the entire point of putting a map
// on a question.
//
// Run:  node tools/fetch-us-map.js

const fs = require('fs');
const path = require('path');

const UA = 'BirdWatchAI-Classroom/1.0 (educational bird-feeder project; '
         + 'contact via project repository)';

const FILE = 'File:Blank US Map (states only).svg';

// Only licences that need no on-slide credit and no share-alike obligation on
// the surrounding page. A map is structural furniture rather than content, so
// a share-alike licence here would reach further than it should.
const OK = /^(cc0|public domain|pd-|no restrictions)/i;

(async () => {
    const api = 'https://commons.wikimedia.org/w/api.php?action=query&format=json'
              + '&prop=imageinfo&iiprop=url|extmetadata&titles=' + encodeURIComponent(FILE);
    const j = await (await fetch(api, { headers: { 'User-Agent': UA } })).json();
    const page = Object.values(j.query.pages)[0];
    const info = page.imageinfo && page.imageinfo[0];
    if (!info) throw new Error('no image info for ' + FILE);

    const meta = info.extmetadata || {};
    const val = k => ((meta[k] || {}).value || '').replace(/<[^>]*>/g, '').trim();
    const licence = val('LicenseShortName');
    if (!OK.test(licence)) throw new Error(`licence not acceptable: ${licence}`);

    const svg = await (await fetch(info.url, { headers: { 'User-Agent': UA } })).text();

    // width/height rather than viewBox: this file carries no viewBox.
    const w = (svg.match(/\swidth="(\d+)"/) || [])[1];
    const h = (svg.match(/\sheight="(\d+)"/) || [])[1];
    if (!w || !h) throw new Error('could not read the map size');

    // Each state is <path class="xx" d="..."><title>Name</title></path>.
    const states = {};
    const names  = {};
    const re = /<path\s+class="([a-z]{2})"\s+d="([^"]+)"\s*>\s*<title>([^<]+)<\/title>/g;
    let m;
    while ((m = re.exec(svg)) !== null) {
        states[m[1]] = m[2];
        names[m[1]]  = m[3];
    }
    if (Object.keys(states).length < 50) {
        throw new Error(`only found ${Object.keys(states).length} states`);
    }

    const out = `// Outlines of the US states, for map questions.
//
// GENERATED by tools/fetch-us-map.js — do not edit by hand.
//
// Source : ${info.descriptionurl}
// Author : ${val('Artist') || 'unknown'}
// Licence: ${licence}
//
// CC0 asks for no attribution. It is recorded anyway, because a future reader
// deserves to know where 50 state outlines came from and on what terms.
//
// Keyed by postal code. The renderer draws these itself rather than embedding
// the SVG as an image, so that any subset of states can be highlighted —
// which is the whole reason a map is on the question at all.
window.US_MAP = {
    viewBox: "0 0 ${w} ${h}",
    source: ${JSON.stringify(info.descriptionurl)},
    licence: ${JSON.stringify(licence)},
    names: ${JSON.stringify(names)},
    paths: ${JSON.stringify(states)}
};
`;

    const dest = path.join('docs', 'js', 'community-us-map.js');
    fs.writeFileSync(dest, out);
    console.log(`  ${Object.keys(states).length} states, ${licence}`);
    console.log(`  ${dest}  ${(out.length / 1024).toFixed(0)}KB`);
})().catch(e => { console.error('  failed:', e.message); process.exit(1); });
